long army::get_AI_target_time(long speed) const
{
    if (can_shoot(0))
        return 1;
    if (!speed)
        return 1;
    long turns = (AI_target_time + speed - 1) / speed;
    if (turns < 1)
        return 1;
    return turns;
}

